void printNextPrime(int n) 
{ 
    int prime;             
    int flag; 
    int count = 0;         
    prime = n + 1;         

    while (count < 10) 
    { 
        flag = 0; 
        for (int i = 2; i <= sqrt(prime); i++) 
        { 
            if (prime % i == 0) 
            { 
                flag = 1; 
                prime++; 
                break; 
            } 
        } 
        if (flag == 0) 
        { 
            cout << prime << " "; 
            prime++; 
            count++; 
        } 
    } 
} 

