func FindDuplicates(arr: [Int])  -> [Int] {
	var seenNumbers = Set<Int>()
	var duplicateValues = [Int]()

	for number in arr {
		if seenNumbers.contains(number) {
			duplicateValues.append(number)
		} else {
			seenNumbers.insert(number)
		}
	}

	return duplicateValues
}

